package mod.cdv.tnpc.tactical;
public class CommandChecks29 {
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static class View extends MotionChecks26.Soldier {public float yaw;public View(MotionChecks26.World w){super(w);}public float getYRot(){return yaw;}public void setYRot(float v){yaw=v;}}
 public static void main(String[]args)throws Exception{var w=new MotionChecks26.World();var n=MotionChecks26.actor(w,3,901);var p=new TacticsChecks24.Target(w);p.x=12;CalmBrain.state(n).target=p;Tactics24.state(n).burstAt=Long.MAX_VALUE;
 boolean handled=true;for(int i=0;i<200;i++){w.now=1000+i;handled&=Tactics24.combat(n);}ok(handled,"ten seconds of combat remain handled without a fallback");ok(n.nav.moves==0,"engaged NPC never strafes or alternates positions just because time passed");ok(!n.pose.toString().equals("SWIMMING"),"no periodic prone stance in combat");ok(n.shift&&!n.sprint,"stable aimed crouch at medium distance");
 var s=Command29.state(n);Command29.order(s,"advance",new double[]{8,0,0},1200,80);s.covered=false;w.now=1200;Tactics24.combat(n);double[] original=s.point.clone();int paths=n.nav.moves;for(int i=1201;i<1220;i++){w.now=i;p.x+=.01;Tactics24.combat(n);}ok(java.util.Arrays.equals(s.point,original),"committed navigation destination is not re-written every frame");ok(n.nav.moves==paths,"navigation request is held for thirty ticks rather than restarted repeatedly");
 p.x=1;w.now=1220;Tactics24.combat(n);ok(s.point==null,"point-blank enemy can interrupt movement immediately");
 p.x=12;w.now=1300;w.rayBlocked=true;n.holder.reloadStateType="RELOADING_FEEDING";Tactics24.combat(n);ok(s.mode.equals("cover_move")&&s.point!=null,"reload chooses an actually occluded reachable cover");double[]cover=s.point.clone();w.now=1310;p.x=13;Tactics24.combat(n);ok(java.util.Arrays.equals(cover,s.point),"moving to cover keeps selected cover despite target motion");n.x=cover[0];n.y=cover[1];n.z=cover[2];w.now=1320;Tactics24.combat(n);ok(s.mode.equals("cover")&&!n.sprint&&s.point==null,"arrival completes movement and holds cover");ok(Command29.coverActive(n),"engineering recognizes deliberate cover pause");p.visible=false;w.now=1321;Tactics24.combat(n);ok(s.mode.equals("cover"),"losing line of sight after arrival does not cancel cover and run outside");CalmBrain.state(n).target=null;w.now=1322;ok(Command29.resume(n)&&s.mode.equals("cover"),"reload cover continues even after acquisition drops the unseen contact");CalmBrain.state(n).target=p;p.visible=true;
 int nativeMoves=n.nav.moves;TeamBrain.move(n,20,0,20,1);ok(n.nav.moves==nativeMoves,"old blocked-shot movement cannot override committed controller navigation");var civilian=MotionChecks26.actor(w,1,907);TeamBrain.move(civilian,2,0,0,1);ok(civilian.nav.moves==1,"native navigation is preserved outside controlled combat");
 n.holder.reloadStateType="NOT_RELOADING";w.now=1330;Tactics24.combat(n);ok(s.mode.equals("cover"),"finishing reload does not instantly bounce out of cover");
 var quiet=MotionChecks26.actor(w,3,903);quiet.x=0;p.x=12;CalmBrain.state(quiet).target=p;Tactics24.state(quiet).burstAt=Long.MAX_VALUE;w.now=1400;Tactics24.combat(quiet);Sense28.hear(quiet,-6,0,0,3,1400);p.visible=false;w.now=1401;ok(!Sense28.tick(quiet),"brief combat contact loss is not replaced by a left-right ambient scan");p.visible=true;
 var follow=MotionChecks26.actor(w,3,905);p.x=8;p.y=0;w.now=1500;Threat27.heard(follow,p,1500);Threat27.acquire(follow,CalmBrain.state(follow),1500,false);ok(CalmBrain.state(follow).target==p,"visible hostile player acquired");p.visible=false;w.now=1510;Social.mem(follow).nextAcquire=0;Threat27.acquire(follow,CalmBrain.state(follow),1510,false);ok(CalmBrain.state(follow).target==p,"a short occlusion preserves contact identity");ok(!Threat27.allowed(follow,p),"retained identity does not grant a shot through cover");w.now=1550;Social.mem(follow).nextAcquire=0;Threat27.acquire(follow,CalmBrain.state(follow),1550,false);ok(CalmBrain.state(follow).target==null,"unseen contact still expires instead of tracking forever");
 var watcher=new View(w);watcher.setYRot(10);watcher.setYHeadRot(40);var fake=new View(w);Client26.pose(watcher,fake);ok(fake.getYRot()==10&&fake.getYHeadRot()==40,"render keeps separate body and head bearings while observing");
 watcher.setYRot(0);watcher.setYHeadRot(0);Sense28.hear(watcher,8,0,0,3,1600);w.now=1600;ok(Sense28.tick(watcher)&&watcher.getYHeadRot()!=0&&watcher.getYRot()==0,"observing a sound initially turns head without snapping whole body");
 var aiming=new View(w);p.visible=true;p.x=12;p.z=0;w.now=1700;Aim29.face(aiming,p);float first=aiming.getYRot();Aim29.face(aiming,p);ok(Math.abs(first)<=12&&aiming.getYRot()==first,"multiple aim calls cannot accelerate turning within the same tick");aiming.setYRot(170);Aim29.face(aiming,p);ok(aiming.getYRot()==first,"navigation yaw overwrite is corrected without snapping aim to target");
 System.out.println("COMMITTED_DECISIONS_CONTACT_COVER_STANCE_CHECKS="+checks);
 }
}
